AR","domain":"BOOLEAN","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-DS","scope_ref":"P2","token":"ds","meaning":"不合格成品是否拆解","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"BOOLEAN","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-E","scope_ref":"P2","token":"E","meaning":"不合格成品进入拆解决策后的期望后续净成本","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-PROFIT","scope_ref":"P2","token":"profit","meaning":"单位成品期望利润","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-A","scope_ref":"P3","token":"a","meaning":"装配成本","unit":"dimensionless","role":"PARAMETER","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-AV","scope_ref":"P3","token":"av","meaning":"节点v装配成本","unit":"dimensionless","role":"PARAMETER","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-DV","scope_ref":"P3","token":"dv","meaning":"节点v输出是否检测","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"BOOLEAN","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-PV","scope_ref":"P3","token":"pv","meaning":"节点v次品率","unit":"dimensionless","role":"PARAMETER","shape":"SCALAR","domain":"PROBABILITY","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-RV","scope_ref":"P3","token":"rv","meaning":"节点v不合格输出是否拆解","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"BOOLEAN","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-SV","scope_ref":"P3","token":"sv","meaning":"节点v拆解费用","unit":"dimensionless","role":"PARAMETER","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-TV","scope_ref":"P3","token":"tv","meaning":"节点v检测成本","unit":"dimensionless","role":"PARAMETER","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-PROFIT3","scope_ref":"P3","token":"profit3","meaning":"问题3期望利润","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-K","scope_ref":"P4","token":"k","meaning":"抽样不合格品数","unit":"dimensionless","role":"PARAMETER","shape":"SCALAR","domain":"NONNEGATIVE_INTEGER","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-N4","scope_ref":"P4","token":"n4","meaning":"问题4抽样样本量","unit":"dimensionless","role":"PARAMETER","shape":"SCALAR","domain":"NONNEGATIVE_INTEGER","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-PROFIT4","scope_ref":"P4","token":"profit4","meaning":"问题4后验期望利润","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"REAL","index_set":[]}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-INDEP-BINOMIAL","scope_ref":"P1","statement":"每件零配件、半成品、成品的合格与否相互独立，且同批次内次品率恒定，因此抽样中不合格品数服从二项分布。","source_type":"GIVEN","justification_refs":["R-OUT"],"risk_level":"LOW","testable":true,"sensitivity_refs":[],"status":"ACTIVE","shared":true,"e1_span":"每件零配件、半成品、成品的合格与否相互独立，且同批次内次品率恒定，因此抽样中不合格品数服从二项分布"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-EXPECTED-PROFIT","scope_ref":"P2","statement":"企业以单位成品的期望利润最大化为唯一决策目标，不考虑风险偏好、库存约束、产能限制等其它因素。","source_type":"MODELING_CHOICE","justification_refs":["R-OUT"],"risk_level":"MEDIUM","testable":false,"sensitivity_refs":[],"status":"ACTIVE","shared":true,"e1_span":"企业以单位成品的期望利润最大化为唯一决策目标，不考虑风险偏好、库存约束、产能限制等其它因素"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-INFINITE-HORIZON","scope_ref":"P2","statement":"问题 2、3 中拆解与调换回流形成的循环按稳态期望值处理，即用不动点方程刻画回流成本，不考虑有限批次内的动态库存效应。","source_type":"MODELING_CHOICE","justification_refs":["R-Q2"],"risk_level":"MEDIUM","testable":false,"sensitivity_refs":[],"status":"ACTIVE","shared":true,"e1_span":"问题 2、3 中拆解与调换回流形成的循环按稳态期望值处理，即用不动点方程刻画回流成本，不考虑有限批次内的动态库存效应"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-CONSERVATIVE-ALPHA","scope_ref":"P1","statement":"抽样方案按保守原则设计：实际犯第一类错误的概率不超过名义显著性水平，实际置信度不低于名义信度，即用离散分布的分位数取整时向保守方向取整。","source_type":"MODELING_CHOICE","justification_refs":["R-Q1"],"risk_level":"LOW","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"抽样方案按保守原则设计：实际犯第一类错误的概率不超过名义显著性水平，实际置信度不低于名义信度，即用离散分布的分位数取整时向保守方向取整"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-NO-DAMAGE-DISASSEMBLY","scope_ref":"P2","statement":"拆解过程不会对零配件造成损坏，拆解出的零配件与原始零配件具有相同的次品率和后续处理成本。","source_type":"GIVEN","justification_refs":["R-Q2"],"risk_level":"LOW","testable":false,"sensitivity_refs":[],"status":"ACTIVE","shared":true,"e1_span":"拆解过程不会对零配件造成损坏，拆解出的零配件与原始零配件具有相同的次品率和后续处理成本"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-SINGLE-RETURN","scope_ref":"P2","statement":"用户退回的不合格品只经过一次拆解/丢弃决策，不产生二次调换循环；调换损失按每件不合格品固定计。","source_type":"MODELING_CHOICE","justification_refs":["R-Q2"],"risk_level":"MEDIUM","testable":false,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"用户退回的不合格品只经过一次拆解/丢弃决策，不产生二次调换循环"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-TREE-STRUCTURE","scope_ref":"P3","statement":"装配结构为树形，每个半成品/成品由确定的子节点装配而成，不存在一个零配件同时进入两个不同半成品的共享情况（图 1 满足此条件）。","source_type":"GIVEN","justification_refs":["R-Q3"],"risk_level":"LOW","testable":false,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"装配结构为树形，每个半成品/成品由确定的子节点装配而成，不存在一个零配件同时进入两个不同半成品的共享情况（图 1 满足此条件）"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-INDEP-NODES","scope_ref":"P3","statement":"不同节点的次品率相互独立，父节点的次品率是在所有子节点输出均合格的条件下装配失败的条件概率。","source_type":"GIVEN","justification_refs":["R-Q3"],"risk_level":"LOW","testable":false,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"不同节点的次品率相互独立，父节点的次品率是在所有子节点输出均合格的条件下装配失败的条件概率"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-BETA-PRIOR","scope_ref":"P4","statement":"次品率参数的先验取无信息 Beta(1,1) 分布，表示在抽样前对次品率无先验偏好；若题面或实际有历史数据，可替换为相应的 Beta 先验。","source_type":"MODELING_CHOICE","justification_refs":["R-Q4"],"risk_level":"MEDIUM","testable":false,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"次品率参数的先验取无信息 Beta(1,1) 分布，表示在抽样前对次品率无先验偏好"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-SAME-SAMPLE-SIZE","scope_ref":"P4","statement":"问题 4 中各零配件、半成品、成品的抽样检测样本量采用问题 1 设计的最小样本量，或题面另行给定的样本量；抽样结果（不合格数）作为已知数据输入。","source_type":"MODELING_CHOICE","justification_refs":["R-Q4"],"risk_level":"MEDIUM","testable":false,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"问题 4 中各零配件、半成品、成品的抽样检测样本量采用问题 1 设计的最小样本量，或题面另行给定的样本量"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-Q1-C1","scope_ref":"P1","expression":"P_{p_0}(X\ge c_1)\le 0.05","representation":"LATEX_PRESENTATION","lhs_symbols":["S-C1"],"rhs_symbols":["S-P0","S-ALPHA1"],"equation_type":"CONSTRAINT","unit":"dimensionless","depends_on":[],"source":"R-Q1","e1_span":"P_{p_0}(X\ge c_1)\le 0.05"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-Q1-C2","scope_ref":"P1","expression":"P_{p_0}(X\le c_2)\ge 0.90","representation":"LATEX_PRESENTATION","lhs_symbols":["S-C2"],"rhs_symbols":["S-P0","S-BETA2"],"equation_type":"CONSTRAINT","unit":"dimensionless","depends_on":[],"source":"R-Q1","e1_span":"P_{p_0}(X\le c_2)\ge 0.90"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-Q2-E","scope_ref":"P2","expression":"E = \min\{0,\; -s + E_{\text{parts}}\}","representation":"LATEX_PRESENTATION","lhs_symbols":["S-E"],"rhs_symbols":["S-S"],"equation_type":"DEFINITION","unit":"dimensionless","depends_on":[],"source":"R-Q2","e1_span":"E = \min\{0,\; -s + E_{\text{parts}}\}"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-Q4-POSTERIOR","scope_ref":"P4","expression":"p \mid k \sim \mathrm{Beta}(k+1,\; n-k+1)","representation":"LATEX_PRESENTATION","lhs_symbols":[],"rhs_symbols":["S-K","S-N4"],"equation_type":"DEFINITION","unit":"dimensionless","depends_on":[],"source":"R-Q4","e1_span":"p \mid k \sim \mathrm{Beta}(k+1,\; n-k+1)"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-Q4-EXPECTATION","scope_ref":"P4","expression":"\mathbb{E}_{p\mid \text{data}}[F(p)] = \int F(p)\,\pi(p\mid \text{data})\,\mathrm{d}p","representation":"LATEX_PRESENTATION","lhs_symbols":["S-PROFIT4"],"rhs_symbols":["S-K","S-N4"],"equation_type":"OBJECTIVE","unit":"dimensionless","depends_on":["EQ-Q4-POSTERIOR"],"source":"R-Q4","e1_span":"\mathbb{E}_{p\mid \text{data}}[F(p)] = \int F(p)\,\pi(p\mid \text{data})\,\mathrm{d}p"}},{"kind":"ModelSpec","value":{"model_id":"M1","problem_refs":["P1"],"assumption_refs":["A-INDEP-BINOMIAL","A-CONSERVATIVE-ALPHA"],"variable_refs":["S-N","S-C1","S-C2"],"parameter_refs":[{"symbol_ref":"S-P0","value":0.1},{"symbol_ref":"S-ALPHA1","value":0.05},{"symbol_ref":"S-BETA2","value":0.10}],"equation_refs":["EQ-Q1-C1","EQ-Q1-C2"],"constraints":[],"objective":"最小化样本量 n 同时满足两类信度约束","dependencies":[]}},{"kind":"ModelSpec","value":{"model_id":"M2","problem_refs":["P2"],"assumption_refs":["A-EXPECTED-PROFIT","A-INFINITE-HORIZON","A-NO-DAMAGE-DISASSEMBLY","A-SINGLE-RETURN","A-INDEP-BINOMIAL"],"variable_refs":["S-D1","S-D2","S-DF","S-DS","S-E","S-PROFIT"],"parameter_refs":[{"symbol_ref":"S-P1","value":0.1},{"symbol_ref":"S-P2","value":0.1},{"symbol_ref":"S-PF","value":0.1},{"symbol_ref":"S-U1","value":10},{"symbol_ref":"S-U2","value":10},{"symbol_ref":"S-T1","value":1},{"symbol_ref":"S-T2","value":1},{"symbol_ref":"S-TF","value":1},{"symbol_ref":"S-S","value":5},{"symbol_ref":"S-L","value":100},{"symbol_ref":"S-R","value":200}],"equation_refs":["EQ-Q2-E"],"constraints":[],"objective":"最大化单位成品期望利润","dependencies":[]}},{"kind":"ModelSpec","value":{"model_id":"M3","problem_refs":["P3"],"assumption_refs":["A-EXPECTED-PROFIT","A-INFINITE-HORIZON","A-TREE-STRUCTURE","A-INDEP-NODES","A-NO-DAMAGE-DISASSEMBLY"],"variable_refs":["S-DV","S-RV","S-PROFIT3"],"parameter_refs":[{"symbol_ref":"S-A","value":5},{"symbol_ref":"S-AV","value":5},{"symbol_ref":"S-PV","value":0.1},{"symbol_ref":"S-SV","value":5},{"symbol_ref":"S-TV","value":1}],"equation_refs":[],"constraints":[],"objective":"最大化多工序装配树的期望利润","dependencies":[]}},{"kind":"ModelSpec","value":{"model_id":"M4","problem_refs":["P4"],"assumption_refs":["A-BETA-PRIOR","A-SAME-SAMPLE-SIZE","A-INDEP-BINOMIAL","A-EXPECTED-PROFIT"],"variable_refs":["S-PROFIT4"],"parameter_refs":[{"symbol_ref":"S-K","value":1},{"symbol_ref":"S-N4","value":10}],"equation_refs":["EQ-Q4-POSTERIOR","EQ-Q4-EXPECTATION"],"constraints":[],"objective":"最大化后验期望利润","dependencies":[]}}],"code":"const fs = require('fs');
function binomPmf(n, k, p) {
  if (k < 0 || k > n) return 0;
  let logP = 0;
  for (let i = 1; i <= k; i++) logP += Math.log(n - k + i) - Math.log(i);
  logP += k * Math.log(p) + (n - k) * Math.log(1 - p);
  return Math.exp(logP);
}
function binomTailUpper(n, c, p) {
  let s = 0;
  for (let k = c; k <= n; k++) s += binomPmf(n, k, p);
  return s;
}
function binomTailLower(n, c, p) {
  let s = 0;
  for (let k = 0; k <= c; k++) s += binomPmf(n, k, p);
  return s;
}
const p0 = 0.1, alpha1 = 0.05, beta2 = 0.10;
let n1 = -1, c1 = -1;
for (let n = 1; n <= 2000; n++) {
  let found = false;
  for (let c = 1; c <= n; c++) {
    if (binomTailUpper(n, c, p0) <= alpha1 + 1e-12) { n1 = n; c1 = c; found = true; break; }
  }
  if (found) break;
}
let n2 = -1, c2 = -1;
for (let n = 1; n <= 2000; n++) {
  let found = false;
  for (let c = n; c >= 0; c--) {
    if (binomTailLower(n, c, p0) >= (1 - beta2) - 1e-12) { n2 = n; c2 = c; found = true; break; }
  }
  if (found) break;
}
const alpha1_actual = binomTailUpper(n1, c1, p0);
const beta2_actual = 1 - binomTailLower(n2, c2, p0);
function q2Profit(pr, d1, d2, df, ds) {
  const p1e = d1 ? 0 : pr.p1;
  const p2e = d2 ? 0 : pr.p2;
  const pBoth = (1 - p1e) * (1 - p2e);
  const pGood = pBoth * (1 - pr.pf);
  const pDef = pBoth * pr.pf;
  const partCost = (pr.u1 + d1 * pr.t1) + (pr.u2 + d2 * pr.t2);
  const testCost = df * pr.tf;
  const replLoss = (df === 0) ? pDef * pr.L : 0;
  const disCost = pDef * (ds ? (pr.s - pr.u1 - pr.u2) : 0);
  return pr.R * pGood - partCost - testCost - replLoss - disCost;
}
function q2Optimal(pr) {
  let best = -Infinity;
  for (let d1 = 0; d1 <= 1; d1++)
    for (let d2 = 0; d2 <= 1; d2++)
      for (let df = 0; df <= 1; df++)
        for (let ds = 0; ds <= 1; ds++) {
          const v = q2Profit(pr, d1, d2, df, ds);
          if (v > best) best = v;
        }
  return best;
}
const cases = [
  {p1:0.1,p2:0.1,pf:0.1,u1:10,u2:10,t1:1,t2:1,tf:1,s:5,L:100,R:200},
  {p1:0.2,p2:0.1,pf:0.1,u1:10,u2:10,t1:1,t2:1,tf:1,s:5,L:100,R:200},
  {p1:0.1,p2:0.2,pf:0.1,u1:10,u2:10,t1:1,t2:1,tf:1,s:5,L:100,R:200},
  {p1:0.1,p2:0.1,pf:0.2,u1:10,u2:10,t1:1,t2:1,tf:1,s:5,L:100,R:200},
  {p1:0.2,p2:0.2,pf:0.2,u1:10,u2:10,t1:1,t2:1,tf:1,s:5,L:100,R:200},
  {p1:0.1,p2:0.1,pf:0.1,u1:20,u2:20,t1:2,t2:2,tf:2,s:10,L:200,R:400}
];
const q2profits = cases.map(function(c){ return q2Optimal(c); });
function q3Profit() {
  const pPart = 0.1, uPart = 10, tPart = 1;
  const pSemi = 0.05, aSemi = 5, tSemi = 1;
  const pFin = 0.1, aFin = 10, tFin = 1, sFin = 5;
  const L = 100, R = 500;
  let best = -Infinity;
  for (let mask = 0; mask < 8192; mask++) {
    let pEff = 1, cost = 0;
    for (let i = 0; i < 8; i++) {
      const d = (mask >> i) & 1;
      pEff *= (1 - (d ? 0 : pPart));
      cost += uPart + d * tPart;
    }
    for (let j = 0; j < 3; j++) {
      const d = (mask >> (8 + j)) & 1;
      pEff *= (1 - pSemi);
      cost += aSemi + d * tSemi;
    }
    const dFin = (mask >> 11) & 1;
    const dDis = (mask >> 12) & 1;
    const pGood = pEff * (1 - pFin);
    const pDef = pEff * pFin;
    cost += aFin + dFin * tFin;
    const replLoss = (dFin === 0) ? pDef * L : 0;
    const disCost = pDef * (dDis ? (sFin - 8 * uPart) : 0);
    const profit = R * pGood - cost - replLoss - disCost;
    if (profit > best) best = profit;
  }
  return best;
}
const q3profit = q3Profit();
